// Compare exact generated bytes; no bytecode, VK, or metadata fields are omitted.
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { ROOT, assertNodeVersion } from './toolchain.mjs';

assertNodeVersion();
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const [mode, first, second] = process.argv.slice(2);

function snapshot() {
  const files = new Set([
    '.build/contracts-manifest.json', '.build/sdk/sdk-manifest.json',
    'apps/dist/sdk-manifest.json', 'apps/dist/crs/crs-manifest.json',
    'apps/src/billboard/billboard_artifact.json',
    'apps/src/billboard/deploy/billboard_artifact.json',
    'apps/src/billboard/censor/billboard_artifact.json',
    'apps/src/billboard/portal_bytecode.txt',
    'apps/src/billboard/deploy/portal_bytecode.txt',
    'billboard/portal/out/BillboardPortal.sol/BillboardPortal.json',
  ]);
  const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, '.build/sdk/sdk-manifest.json')));
  for (const name of Object.keys(manifest.outputs)) {
    if (path.basename(name) !== name) throw new Error(`Invalid SDK output name: ${name}`);
    files.add(`.build/sdk/${name}`);
    files.add(`apps/dist/${name}`);
  }
  function apps(directory) {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      if (entry.isDirectory()) apps(path.join(directory, entry.name));
      if (entry.isFile() && entry.name === 'template.html') {
        files.add(`apps/dist/${path.basename(directory)}.html`);
      }
    }
  }
  apps(path.join(ROOT, 'apps/src'));
  // Provisioned CRS files are content-pinned and restored by build:crs. Include
  // all bytes and their copied manifest in exact output comparisons.
  for (const name of ['g1.dat', 'g2.dat', 'grumpkin_g1.dat']) files.add(`apps/dist/crs/${name}`);
  return { schema: 1, algorithm: 'sha256', files: Object.fromEntries(
    [...files].sort().map(name => [name, sha(fs.readFileSync(path.join(ROOT, name)))])
  ) };
}

if (mode === 'snapshot' && first && !second) {
  const result = snapshot();
  fs.mkdirSync(path.dirname(path.resolve(first)), { recursive: true });
  fs.writeFileSync(first, JSON.stringify(result, null, 2) + '\n');
  console.log(`Recorded ${Object.keys(result.files).length} exact output hashes in ${first}`);
} else if (mode === 'compare' && first && second) {
  const before = JSON.parse(fs.readFileSync(first));
  const after = JSON.parse(fs.readFileSync(second));
  for (const manifest of [before, after]) {
    if (manifest.schema !== 1 || manifest.algorithm !== 'sha256' || !manifest.files ||
        Object.keys(manifest.files).length === 0 ||
        Object.values(manifest.files).some(hash => !/^[0-9a-f]{64}$/.test(hash))) {
      throw new Error('Invalid or empty reproducibility snapshot');
    }
  }
  const differences = [...new Set([...Object.keys(before.files), ...Object.keys(after.files)])]
    .sort().filter(name => before.files[name] !== after.files[name]);
  if (differences.length) throw new Error(`Build outputs differ:\n${differences.join('\n')}`);
  console.log(`PASS: ${Object.keys(before.files).length} output files match byte-for-byte.`);
} else {
  throw new Error('Usage: node scripts/check-reproducibility.mjs snapshot OUTPUT.json | compare FIRST.json SECOND.json');
}
